  // apps/commerce/web/src/lib/theme-engine/madeyours-personalization.ts
  function bindMadeYoursPersonalization(element) {
    if (element.dataset.lbPersonalizationRequired !== "true") return null;
    const purchase = element.querySelector("[data-lb-add-to-cart]");
    if (purchase) purchase.disabled = true;
    let raw;
    try {
      raw = JSON.parse(element.dataset.lbPersonalizationFacts || "null");
    } catch {
      return null;
    }
    const parsed = PersonalizationFactsSchema.safeParse(raw);
    if (!parsed.success) return null;
    const facts = parsed.data;
    const root = element.querySelector("[data-lb-personalization]");
    if (!root || !purchase) return null;
    const method = root.querySelector("[data-lb-personalization-method]");
    const text7 = root.querySelector("[data-lb-personalization-text]");
    const style = root.querySelector("[data-lb-personalization-style]");
    const placement = root.querySelector("[data-lb-personalization-placement]");
    const reviewButton = root.querySelector("[data-lb-personalization-review]");
    const fields = root.querySelector("[data-lb-personalization-fields]");
    const summary = root.querySelector("[data-lb-personalization-summary]");
    const error48 = root.querySelector("[data-lb-personalization-error]");
    if (!method || !text7 || !style || !placement || !reviewButton || !fields || !summary || !error48) return null;
    const removers = [];
    let basePurchasable = false;
    let reviewedFingerprint = null;
    let state;
    let destroyed = false;
    const read = () => ({ method_id: method.value, style_id: style.value, placement_id: placement.value, text: text7.value });
    const put = (selector, value) => {
      const node = root.querySelector(selector);
      if (node) node.textContent = value;
    };
    const listen = (node, event, callback) => {
      node.addEventListener(event, callback);
      removers.push(() => node.removeEventListener(event, callback));
    };
    const setStage = (stage) => {
      root.querySelectorAll("[data-lb-personalization-stage]").forEach((node) => node.dataset.lbPersonalizationStage === stage ? node.setAttribute("aria-current", "step") : node.removeAttribute("aria-current"));
    };
    const refreshPurchase = () => {
      const current = reviewPersonalization(facts, read());
      purchase.disabled = destroyed || !basePurchasable || !current.valid || current.fingerprintInput !== reviewedFingerprint;
    };
    const paintPreview = () => {
      const preview = root.querySelector("[data-lb-personalization-preview]");
      if (preview) preview.hidden = !state?.lastValidPreview;
      put("[data-lb-personalization-preview-text]", state?.lastValidPreview?.text || "");
      const accepted = state?.lastValidPreview;
      const output = root.querySelector("[data-lb-personalization-preview-text]");
      if (output) output.style.fontFamily = accepted?.style.id === "serif" ? "Georgia, serif" : "inherit";
      put("[data-lb-personalization-preview-note]", accepted ? `${state && !state.review.valid ? "Showing the last valid text. Your current draft has errors. " : ""}${accepted.style.label} \xB7 ${accepted.placement.label}` : "");
    };
    const normalize = element.ownerDocument.createElement("button");
    normalize.type = "button";
    normalize.className = "my-link";
    normalize.hidden = true;
    normalize.textContent = "Use suggested text";
    normalize.dataset.lbPersonalizationNormalize = "";
    error48.after(normalize);
    const paintErrors = (visible) => {
      const problems = state && !state.review.valid ? state.review.issues : [];
      error48.textContent = visible ? problems.map((issue2) => issue2.message).join(" ") : "";
      error48.hidden = !visible || problems.length === 0;
      text7.setAttribute("aria-invalid", visible && problems.some((issue2) => issue2.field === "text") ? "true" : "false");
      const suggestion = problems.find((issue2) => issue2.code === "NORMALIZE_TEXT")?.suggested_text;
      normalize.hidden = !visible || !suggestion;
      normalize.textContent = suggestion ? `Use suggested text: ${suggestion}` : "Use suggested text";
    };
    const update = (showErrors = true) => {
      state = updatePersonalizationDraft(facts, read(), state);
      reviewedFingerprint = null;
      summary.hidden = true;
      fields.hidden = false;
      reviewButton.hidden = false;
      setStage("specify");
      paintPreview();
      paintErrors(showErrors);
      refreshPurchase();
    };
    const populateChoices = () => {
      const chosen = facts.methods.find((item) => item.id === method.value) || facts.methods[0];
      method.value = chosen.id;
      const fill = (select, choices) => {
        const prior = select.value;
        select.replaceChildren(...choices.map((choice3) => {
          const option = element.ownerDocument.createElement("option");
          option.value = choice3.id;
          option.textContent = choice3.label;
          return option;
        }));
        if (choices.some((choice3) => choice3.id === prior)) select.value = prior;
      };
      fill(style, chosen.styles);
      fill(placement, chosen.placements);
      put("[data-lb-personalization-help]", `${chosen.min_graphemes}\u2013${chosen.max_graphemes} characters. ${chosen.character_set === "latin-name" ? "A\u2013Z letters" : "Letters"}, spaces, apostrophes and hyphens.`);
    };
    listen(method, "change", () => {
      populateChoices();
      update();
    });
    for (const input of [text7, style, placement]) listen(input, input === text7 ? "input" : "change", () => update());
    listen(normalize, "click", () => {
      const suggestion = state && !state.review.valid ? state.review.issues.find((issue2) => issue2.code === "NORMALIZE_TEXT")?.suggested_text : void 0;
      if (suggestion) {
        text7.value = suggestion;
        update();
        text7.focus();
      }
    });
    listen(reviewButton, "click", () => {
      state = updatePersonalizationDraft(facts, read(), state);
      paintPreview();
      paintErrors(true);
      if (!state.review.valid) {
        text7.focus();
        refreshPurchase();
        return;
      }
      const accepted = state.review.accepted;
      put("[data-lb-personalization-summary-text]", accepted.text);
      put("[data-lb-personalization-summary-method]", accepted.method.label);
      put("[data-lb-personalization-summary-style]", accepted.style.label);
      put("[data-lb-personalization-summary-placement]", accepted.placement.label);
      reviewedFingerprint = state.review.fingerprintInput;
      summary.hidden = false;
      fields.hidden = true;
      reviewButton.hidden = true;
      setStage("review");
      summary.tabIndex = -1;
      summary.focus();
      refreshPurchase();
    });
    const edit = root.querySelector("[data-lb-personalization-edit]");
    if (edit) listen(edit, "click", () => {
      update(false);
      text7.focus();
    });
    const unavailable = root.querySelector("[data-lb-personalization-unavailable]");
    if (unavailable) unavailable.hidden = true;
    populateChoices();
    reviewButton.disabled = false;
    update(false);
    return {
      setBasePurchasable(value) {
        basePurchasable = value;
        refreshPurchase();
      },
      readReviewedDraft() {
        if (destroyed || !basePurchasable) return null;
        const draft = read();
        const current = reviewPersonalization(facts, draft);
        return current.valid && current.fingerprintInput === reviewedFingerprint ? { ...draft } : null;
      },
      destroy() {
        destroyed = true;
        reviewedFingerprint = null;
        removers.forEach((remove) => remove());
        normalize.remove();
        purchase.disabled = true;
        reviewButton.disabled = true;
        if (unavailable) unavailable.hidden = false;
      }
    };
  }

  // docs/implementation/niche-themes-2026-10-23/madeyours/personalization-browser.ts
  var controllers = Array.from(document.querySelectorAll("lb-add-to-cart")).map((element) => {
    const controller = bindMadeYoursPersonalization(element);
    controller?.setBasePurchasable(document.body.dataset.fixtureBaseAvailable === "true");
    return controller;
  }).filter((controller) => controller !== null);
  Object.assign(window, { madeyoursFixture: { draft: () => controllers[0]?.readReviewedDraft() ?? null, destroy: () => controllers.forEach((controller) => controller?.destroy()) } });
